_OBJECT_RE = re.compile(r"^[0-9a-f]{40}$")
_TEST_COUNT_RE = re.compile(r"Ran (\d+) tests?")


def _git(repo: Path, *args: str) -> str:
    env = {key: value for key, value in os.environ.items() if not key.startswith("GIT_")}
    result = subprocess.run(
        ["/usr/bin/git", "-C", str(repo), *args],
        capture_output=True,
        text=True,
        env=env,
    )
    value = result.stdout.strip()
    if result.returncode != 0 or not _OBJECT_RE.fullmatch(value):
        raise SystemExit("无法绑定产品能力门的候选源码身份")
    return value


def run_capability_gate(*, repo: Path, candidate: str = "HEAD") -> dict:
    repo = Path(repo).resolve()
    app = repo / "app"
    candidate_commit = _git(repo, "rev-parse", "--verify", f"{candidate}^{{commit}}")
    candidate_tree = _git(repo, "rev-parse", "--verify", f"{candidate_commit}^{{tree}}")
    env = os.environ.copy()
    env.update(
        {
            "PYTHONDONTWRITEBYTECODE": "1",
            "QT_QPA_PLATFORM": "offscreen",
            "LULU_TEST_SECRET_STORE": "memory",
            "PYTHONPATH": os.pathsep.join((str(app), str(app / "tests"))),
        }
    )
    result = subprocess.run(
        [os.fspath(Path(os.sys.executable)), str(app / "packaging" / "run_product_capability_tests.py"), *CAPABILITY_TESTS],
        cwd=app,
        capture_output=True,
        text=True,
        env=env,
    )
    combined = result.stdout + result.stderr
    if result.returncode != 0:
        raise SystemExit("产品能力门未通过，拒绝打包：\n" + combined[-8000:])
    match = _TEST_COUNT_RE.search(combined)
    if match is None or int(match.group(1)) != len(CAPABILITY_TESTS):
        raise SystemExit("产品能力门结果不完整，拒绝打包")
    return {
        "schema_version": 1,
        "status": "passed",
        "candidate_commit": candidate_commit,
        "candidate_tree": candidate_tree,
        "passed_test_count": int(match.group(1)),
        "capability_tests": list(CAPABILITY_TESTS),
    }


def write_receipt(path: Path, payload: dict) -> dict:
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    handle = tempfile.NamedTemporaryFile(
        mode="w",
        encoding="utf-8",
        dir=path.parent,
        prefix=f".{path.name}.",
        suffix=".tmp",
        delete=False,
    )
    temp_path = Path(handle.name)
    try:
        with handle:
            json.dump(payload, handle, ensure_ascii=False, indent=2, sort_keys=True)
            handle.write("\n")
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temp_path, 0o600)
        os.replace(temp_path, path)
    finally:
        temp_path.unlink(missing_ok=True)
    return payload


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", type=Path, default=Path(__file__).resolve().parents[2])
    parser.add_argument("--candidate", default="HEAD")
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    receipt = write_receipt(
        args.output,
        run_capability_gate(repo=args.repo, candidate=args.candidate),
    )
    print(
        f"完整产品能力校验通过：{receipt['passed_test_count']} 项 · "
        f"{receipt['candidate_commit'][:12]}"
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
